// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';
import { Checkout } from './Checkout';
import { axe, toHaveNoViolations } from 'jest-axe';

expect.extend(toHaveNoViolations);

// Arrange the board pieces
const mockCartContext = {
  items: [{ id: '1', name: 'Widget', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn(),
};

const mockPaymentContext = {
  processPayment: vi.fn(),
};

vi.mock('./CartContext', () => ({
  useCart: () => mockCartContext,
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => mockPaymentContext,
}));

describe('Checkout - The game proceeds as expected', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockPaymentContext.processPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  describe('Happy path - When all players cooperate', () => {
    it('completes checkout flow from shipping to confirmation', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();

      render(<Checkout onComplete={onComplete} />);

      // Shipping step
      await user.type(screen.getByRole('textbox', { name: /street/i }), '123 Sator Square');
      await user.type(screen.getByRole('textbox', { name: /city/i }), 'Ankh-Morpork');
      await user.selectOptions(screen.getByRole('combobox', { name: /state/i }), 'CA');
      await user.type(screen.getByRole('textbox', { name: /zip/i }), '12345');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByRole('textbox', { name: /card number/i }), '4111111111111111');
      await user.type(screen.getByRole('textbox', { name: /expiry/i }), '12/25');
      await user.type(screen.getByRole('textbox', { name: /cvv/i }), '123');
      await user.type(screen.getByRole('textbox', { name: /name on card/i }), 'Havelock Vetinari');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/123 Sator Square/)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByRole('status')).toHaveTextContent('ORD-12345');
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  describe('Validation - Consequences for improper behavior', () => {
    it('displays shipping errors when fields are empty', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByRole('alert')).toHaveTextContent(/street address is required/i);
      expect(screen.getByRole('textbox', { name: /street/i })).toHaveAttribute('aria-invalid', 'true');
    });

    it('rejects invalid ZIP codes', async () => {
      const user = userEvent.setup();
      render(<Checkout />);

      await user.type(screen.getByRole('textbox', { name: /zip/i }), 'ABCDE');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('Empty cart - Do not let me detain you', () => {
    it('displays empty cart message and allows shopping', async () => {
      mockCartContext.items = [];
      const onCancel = vi.fn();

      render(<Checkout onCancel={onCancel} />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
      await userEvent.click(screen.getByRole('button', { name: /continue shopping/i }));
      expect(onCancel).toHaveBeenCalled();
    });
  });

  describe('Payment failure - Even the best-laid plans', () => {
    it('displays error and allows retry when payment fails', async () => {
      mockPaymentContext.processPayment.mockRejectedValueOnce(new Error('Card declined'));
      const user = userEvent.setup();

      // Navigate to review step... then
      await user.click(screen.getByRole('button', { name: /place order/i }));

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  describe('Accessibility - A civilized society accommodates all', () => {
    it('has no accessibility violations', async () => {
      const { container } = render(<Checkout />);
      expect(await axe(container)).toHaveNoViolations();
    });
  });
});
